import{_ as a,o as l,c as r,a2 as e}from"./chunks/framework.Dkj3JE0_.js";const c=JSON.parse('{"title":"JLPT N2 计划","description":"","frontmatter":{"title":"JLPT N2 计划"},"headers":[],"relativePath":"zh/blogs/JLPT-N2/plan.md","filePath":"zh/blogs/JLPT-N2/plan.md"}'),i={name:"zh/blogs/JLPT-N2/plan.md"};function n(d,t,s,o,h,g){return l(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="jlpt-n2-学习计划" tabindex="-1">JLPT N2 学习计划 <a class="header-anchor" href="#jlpt-n2-学习计划" aria-label="Permalink to &quot;JLPT N2 学习计划&quot;">​</a></h1><blockquote><p><strong>基本假设：</strong> 考试在 <strong>2026 年 12 月 6 日（周日）</strong>。<strong>10 月 13 日 → 11 月 14 日（周五）<strong>集中学完（软截止 <strong>11 月 16 日</strong>），每天硬上限 <strong>2.0 小时</strong>（每周约 <strong>14 小时</strong>）。<strong>12 月 1–5 日</strong>只作缓冲（复习 ≤1 小时）；12 月</strong>不再开始新内容的第一轮</strong>。不要在 12 月加大强度。</p></blockquote><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><ul><li>在 11 月中旬前清空剩余的词汇队列（约 <strong>2000</strong> 个，每天约 <strong>60</strong> 个）和剩余的视频课（约 <strong>180</strong> 节，每天约 <strong>5–6</strong> 节）。</li><li>借助 Caligo 持续更新语法笔记、例句和错题卡——重点是在语境中认出来，而不只是背卡片。</li><li>晚间练习在语法、真题练习、阅读和听力之间轮换，任何一项技能都不能整整一周不碰。</li><li>进入 12 月时第一轮已全部完成；12 月 1–5 日只做轻量复习和考前安排，迎接 12 月 6 日的考试。</li></ul><h2 id="当前重点-截至-2026-年-10-月-14-日" tabindex="-1">当前重点（截至 2026 年 10 月 14 日） <a class="header-anchor" href="#当前重点-截至-2026-年-10-月-14-日" aria-label="Permalink to &quot;当前重点（截至 2026 年 10 月 14 日）&quot;">​</a></h2><p><strong>今天：</strong> 早上时段刷词汇 App。</p><p><strong>进行中的任务</strong></p><table tabindex="0"><thead><tr><th>任务</th><th style="text-align:right;">剩余（约）</th><th style="text-align:right;">每日进度</th></tr></thead><tbody><tr><td>词汇（App）</td><td style="text-align:right;">约 2000</td><td style="text-align:right;">约 60 / 天</td></tr><tr><td>视频课</td><td style="text-align:right;">约 180</td><td style="text-align:right;">约 5–6 / 天</td></tr><tr><td>语法 / 笔记 / 卡片</td><td style="text-align:right;">与 Caligo 持续进行</td><td style="text-align:right;">周一和周三晚上</td></tr><tr><td>练习 / 阅读 / 听力</td><td style="text-align:right;">晚上轮换</td><td style="text-align:right;">见下方节奏</td></tr></tbody></table><p>当天的词汇完成后，再和 Caligo 一起深入语法和视频——点 Caligo 开始这两部分；不要自己加重晚上的负担。</p><h2 id="每日节奏-硬上限-2-0-小时" tabindex="-1">每日节奏（硬上限 2.0 小时） <a class="header-anchor" href="#每日节奏-硬上限-2-0-小时" aria-label="Permalink to &quot;每日节奏（硬上限 2.0 小时）&quot;">​</a></h2><p>时段不得与 CFA（20:00–02:00）、健身（18:00–20:00）或周一周报时段（08:00–10:00）重叠。</p><table tabindex="0"><thead><tr><th>时段</th><th style="text-align:right;">时间</th><th>内容</th></tr></thead><tbody><tr><td>早晨词汇</td><td style="text-align:right;">06:45–07:15</td><td>App 词汇（约 60 个）。</td></tr><tr><td>早晨视频</td><td style="text-align:right;">07:15–08:05</td><td>视频课（约 5–6 节）。</td></tr><tr><td>晚间轮换</td><td style="text-align:right;">21:00–21:40</td><td>当天的技能（见下表）。</td></tr></tbody></table><h3 id="晚间轮换-21-00–21-40" tabindex="-1">晚间轮换（21:00–21:40） <a class="header-anchor" href="#晚间轮换-21-00–21-40" aria-label="Permalink to &quot;晚间轮换（21:00–21:40）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日</th><th>重点</th></tr></thead><tbody><tr><td>周一</td><td>语法 · 笔记 / 卡片（Caligo）</td></tr><tr><td>周二</td><td>练习（真题式题组）</td></tr><tr><td>周三</td><td>语法 · 笔记 / 卡片（Caligo）</td></tr><tr><td>周四</td><td>阅读</td></tr><tr><td>周五</td><td>听力</td></tr><tr><td>周六</td><td>练习（真题式题组）</td></tr><tr><td>周日</td><td>听力</td></tr></tbody></table><h2 id="冲刺路线" tabindex="-1">冲刺路线 <a class="header-anchor" href="#冲刺路线" aria-label="Permalink to &quot;冲刺路线&quot;">​</a></h2><h3 id="a-阶段——覆盖-10-月-13-日-→-11-月-14-日周五" tabindex="-1">A 阶段——覆盖（10 月 13 日 → 11 月 14 日周五） <a class="header-anchor" href="#a-阶段——覆盖-10-月-13-日-→-11-月-14-日周五" aria-label="Permalink to &quot;A 阶段——覆盖（10 月 13 日 → 11 月 14 日周五）&quot;">​</a></h3><ul><li>守住<strong>每天 2.0 小时</strong>的上限；早上没做完的时间不挤占晚上的 CFA 时段。</li><li>词汇和视频每天按上述速度推进，直到队列清空。</li><li>语法晚：对比相近句型、写短例句、做错题卡——而不是写第二本教材。</li><li>练习 / 阅读 / 听力晚：限时或一遍过；把错题记下来，留给下一次语法或卡片时段。</li></ul><p><strong>软截止：11 月 16 日</strong>——完成剩余的第一轮内容；此后不再开新的语法章节或视频系列。</p><h3 id="b-阶段——缓冲-12-月-1–5-日" tabindex="-1">B 阶段——缓冲（12 月 1–5 日） <a class="header-anchor" href="#b-阶段——缓冲-12-月-1–5-日" aria-label="Permalink to &quot;B 阶段——缓冲（12 月 1–5 日）&quot;">​</a></h3><ul><li>每天只做 <strong>≤1 小时</strong>复习。</li><li>容易混淆的语法对、听力中的薄弱提示词、反复出错的词汇。</li><li>确认考试安排；保证睡眠。</li><li><strong>不学新的第一轮内容。</strong></li></ul><h3 id="考试日——12-月-6-日-周日" tabindex="-1">考试日——12 月 6 日（周日） <a class="header-anchor" href="#考试日——12-月-6-日-周日" aria-label="Permalink to &quot;考试日——12 月 6 日（周日）&quot;">​</a></h3><ul><li>有用的话只做轻度热身；不要临时抱佛脚。</li></ul><h2 id="每周检查-可选的周日记录" tabindex="-1">每周检查（可选的周日记录） <a class="header-anchor" href="#每周检查-可选的周日记录" aria-label="Permalink to &quot;每周检查（可选的周日记录）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>词汇已完成 / 剩余：</span></span>
<span class="line"><span>视频已完成 / 剩余：</span></span>
<span class="line"><span>完成的晚间时段（语法 / 练习 / 阅读 / 听力）：</span></span>
<span class="line"><span>仍然不稳的一个句型或一段文章：</span></span>
<span class="line"><span>下周调整进度吗？（保持上限——不要加时长）</span></span></code></pre></div><h2 id="接下来七天-10-月-14–20-日" tabindex="-1">接下来七天（10 月 14–20 日） <a class="header-anchor" href="#接下来七天-10-月-14–20-日" aria-label="Permalink to &quot;接下来七天（10 月 14–20 日）&quot;">​</a></h2><ul><li>[ ] 每天坚持早晨词汇（06:45–07:15）和视频（07:15–08:05）。</li><li>[ ] 14 日周一 / 16 日周三晚上：点 Caligo 学语法——做笔记和例句卡，而不是拉长时段。</li><li>[ ] 15 日周二 / 18 日周六晚上：练习题组；记录错题。</li><li>[ ] 17 日周四晚上：阅读；18 日周五 / 20 日周日晚上：听力。</li><li>[ ] 守住每天 2.0 小时的上限；不要占用 CFA 夜间时段。</li><li>[ ] 不要安排 12 月的第一轮冲刺。</li></ul>`,26)])])}const b=a(i,[["render",n]]);export{c as __pageData,b as default};
